/* ============ GLOBE 3D (rendu raster ombré) ============
   Les continents sont rasterisés une fois dans une texture équirectangulaire
   (masque terre/mer), puis chaque pixel du disque est projeté à l'envers
   (orthographique) vers (lat, lon) : aucun polygone à découper au limbe, donc
   plus d'artefacts à l'horizon. La géométrie (lat, lon relative, éclairage)
   ne dépend que de l'inclinaison : elle est mise en cache, et la rotation
   horizontale se réduit à un décalage dans la texture — rendu fluide en Retina. */
let GLOBE = null, globeCanvas = null, globeCtx = null, globeAnim = null;
let globeRotY = -0.6, globeRotX = 0.35, globeDrag = null, globeHover = null, globeSelected = null;
let globeTex = null, globeGeo = null, globeImg = null, globeLastInteract = 0;
const GLOBE_TEX_W = 2048, GLOBE_TEX_H = 1024;

function globeTexture() {
  if (globeTex) return globeTex;
  const c = document.createElement('canvas'); c.width = GLOBE_TEX_W; c.height = GLOBE_TEX_H;
  const g = c.getContext('2d');
  g.fillStyle = '#000'; g.fillRect(0, 0, GLOBE_TEX_W, GLOBE_TEX_H);
  g.fillStyle = '#fff';
  for (const ring of CONTINENTS) {
    if (ring.length < 3) continue;
    g.beginPath();
    ring.forEach(([lon, lat], i) => {
      const x = (lon + 180) / 360 * GLOBE_TEX_W, y = (90 - lat) / 180 * GLOBE_TEX_H;
      if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
    });
    g.closePath(); g.fill();
  }
  const d = g.getImageData(0, 0, GLOBE_TEX_W, GLOBE_TEX_H).data;
  const land = new Uint8Array(GLOBE_TEX_W * GLOBE_TEX_H);
  for (let i = 0; i < land.length; i++) land[i] = d[i * 4]; // 0..255 (bords anticrénelés)
  globeTex = land;
  return land;
}

function globeSize() {
  const w = globeCanvas.clientWidth || 620, h = globeCanvas.clientHeight || 460;
  return { w, h, R: Math.min(w, h) * 0.42 };
}

function globeBuildGeometry(dpr) {
  const { w, h, R } = globeSize();
  const W = Math.round(w * dpr), H = Math.round(h * dpr), Rp = R * dpr;
  const cx = W / 2, cy = H / 2;
  const n = W * H;
  const texY = new Int32Array(n).fill(-1), lonRel = new Float32Array(n), shade = new Float32Array(n), spec = new Float32Array(n), rim = new Float32Array(n), edge = new Float32Array(n);
  const cr = Math.cos(globeRotX), sr = Math.sin(globeRotX);
  // lumière venant d'en haut à gauche, légèrement devant
  let L = [-0.45, 0.55, 0.70]; const ln = Math.hypot(...L); L = L.map(v => v / ln);
  const Hh = [L[0], L[1], L[2] + 1]; const hn = Math.hypot(...Hh); const Hv = Hh.map(v => v / hn);
  const y0 = Math.max(0, Math.floor(cy - Rp - 1)), y1 = Math.min(H, Math.ceil(cy + Rp + 1));
  const x0 = Math.max(0, Math.floor(cx - Rp - 1)), x1 = Math.min(W, Math.ceil(cx + Rp + 1));
  for (let py = y0; py < y1; py++) {
    const Y = -(py + 0.5 - cy) / Rp;
    for (let px = x0; px < x1; px++) {
      const X = (px + 0.5 - cx) / Rp;
      const r2 = X * X + Y * Y, rr = Math.sqrt(r2);
      if (rr >= 1 + 1 / Rp) continue;
      const Z = Math.sqrt(Math.max(0, 1 - r2));
      const y = Y * cr + Z * sr, z = -Y * sr + Z * cr;
      const lat = Math.asin(Math.max(-1, Math.min(1, y)));
      const i = py * W + px;
      texY[i] = Math.min(GLOBE_TEX_H - 1, Math.max(0, Math.floor((0.5 - lat / Math.PI) * GLOBE_TEX_H)));
      lonRel[i] = Math.atan2(X, z); // lon + rotY
      const lam = Math.max(0, X * L[0] + Y * L[1] + Z * L[2]);
      shade[i] = 0.22 + 0.9 * lam;
      let sp = Math.max(0, X * Hv[0] + Y * Hv[1] + Z * Hv[2]);
      sp *= sp; sp *= sp; sp *= sp; sp *= sp; sp *= sp; sp *= sp; // ^64, plus rapide que pow
      spec[i] = sp;
      rim[i] = Math.pow(1 - Z, 3); // halo atmosphérique au limbe
      edge[i] = Math.max(0, Math.min(1, (1 - rr) * Rp + 0.5)); // bord anticrénelé
    }
  }
  globeGeo = { W, H, dpr, rotX: globeRotX, cssW: w, cssH: h, texY, lonRel, shade, spec, rim, edge, box: [x0, x1, y0, y1] };
  globeImg = null;
}

function globeRenderSphere() {
  const G = globeGeo, tex = globeTexture();
  if (!globeImg) {
    globeImg = new ImageData(G.W, G.H);
    globeRenderSphere.canvas = Object.assign(document.createElement('canvas'), { width: G.W, height: G.H });
  }
  const d = globeImg.data;
  d.fill(0);
  const twoPi = Math.PI * 2, k = GLOBE_TEX_W / twoPi;
  const [x0, x1, y0, y1] = G.box;
  for (let py = y0; py < y1; py++) {
    for (let px = x0; px < x1; px++) {
      const i = py * G.W + px, ty = G.texY[i];
      if (ty < 0) continue;
      let u = Math.floor((G.lonRel[i] - globeRotY + Math.PI) * k) % GLOBE_TEX_W;
      if (u < 0) u += GLOBE_TEX_W;
      const a = tex[ty * GLOBE_TEX_W + u] / 255; // fraction de terre (bords lissés)
      const lat = Math.abs(90 - ty / GLOBE_TEX_H * 180);
      // terre : vert -> brun avec la latitude, glace aux pôles
      let lr = 46, lg = 125, lb = 50;
      if (lat > 62) { const t = Math.min(1, (lat - 62) / 10); lr += (225 - lr) * t; lg += (232 - lg) * t; lb += (236 - lb) * t; }
      else if (lat < 35 && lat > 12) { lr = 110; lg = 128; lb = 62; }
      // océan : bleu profond, reflet spéculaire
      const s = G.shade[i], sp = G.spec[i] * (1 - a), rm = G.rim[i];
      let r = (14 + (lr - 14) * a) * s + 255 * sp * 0.55;
      let g = (52 + (lg - 52) * a) * s + 255 * sp * 0.6;
      let b = (110 + (lb - 110) * a) * s + 255 * sp * 0.7;
      r += (120 - r) * rm * 0.6; g += (180 - g) * rm * 0.6; b += (255 - b) * rm * 0.6;
      const o = i * 4;
      d[o] = r; d[o + 1] = g; d[o + 2] = b; d[o + 3] = 255 * G.edge[i];
    }
  }
}

function initGlobe() {
  const canvas = document.getElementById('globeCanvas');
  if (!canvas) return;
  globeCanvas = canvas; globeCtx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(canvas.clientWidth * dpr); canvas.height = Math.round(canvas.clientHeight * dpr);
  globeGeo = null;
  canvas.addEventListener('mousedown', e => { globeDrag = {x: e.clientX, y: e.clientY, ry: globeRotY, rx: globeRotX}; globeLastInteract = performance.now(); canvas.style.cursor = 'grabbing'; });
  canvas.addEventListener('mousemove', onGlobeMove);
  canvas.addEventListener('mouseup', e => {
    if (globeDrag && Math.abs(e.clientX-globeDrag.x)<4 && Math.abs(e.clientY-globeDrag.y)<4) onGlobeClick(e);
    globeDrag = null; canvas.style.cursor = 'grab';
  });
  canvas.addEventListener('mouseleave', () => { globeHover = null; });
  if (!initGlobe.bound) {
    initGlobe.bound = true;
    window.addEventListener('mouseup', () => { globeDrag = null; });
    window.addEventListener('mousemove', e => { if (globeDrag && globeCanvas) onGlobeMove(e); });
  }
  if (!globeAnim) globeAnim = requestAnimationFrame(drawGlobe);
}

function onGlobeMove(e) {
  if (!globeDrag) { globeHover = hitGlobe(e); globeCanvas.style.cursor = globeHover ? 'pointer' : 'grab'; return; }
  const { R } = globeSize();
  globeRotY = globeDrag.ry + (e.clientX - globeDrag.x) / R;
  globeRotX = Math.max(-1.2, Math.min(1.2, globeDrag.rx + (e.clientY - globeDrag.y) / R));
  globeLastInteract = performance.now();
}

function globeProject(lat, lon) {
  const { w, h, R } = globeSize();
  const la = lat * Math.PI / 180, lo = lon * Math.PI / 180 + globeRotY;
  const x = Math.cos(la) * Math.sin(lo);
  const y = Math.sin(la);
  const z = Math.cos(la) * Math.cos(lo);
  const y2 = y * Math.cos(globeRotX) - z * Math.sin(globeRotX);
  const z2 = y * Math.sin(globeRotX) + z * Math.cos(globeRotX);
  return { sx: w/2 + x * R, sy: h/2 - y2 * R, z: z2 };
}

function hitGlobe(e) {
  if (!GLOBE || !globeCanvas) return null;
  const rect = globeCanvas.getBoundingClientRect();
  const mx = e.clientX - rect.left, my = e.clientY - rect.top;
  let best = null, bd = 12;
  for (const p of GLOBE.pins) {
    const pr = globeProject(p.lat, p.lon);
    if (pr.z < 0.08) continue;
    const ty = pr.sy - 7 * pr.z; // la tête de l'épingle, pas son pied
    const d = Math.hypot(pr.sx - mx, ty - my);
    if (d < bd) { bd = d; best = p; }
  }
  return best;
}

function onGlobeClick(e) {
  const p = hitGlobe(e);
  globeSelected = p;
  const box = document.getElementById('globeInfo');
  if (!box) return;
  if (!p) { box.innerHTML = '<span class="muted">Cliquez sur une épingle…</span>'; return; }
  box.innerHTML = '<div class="hdr-row">' + esc(p.ticker) + ' <span class="' + (p.direction==='long'?'pos':'neg') + '">' + (p.direction==='long'?'▲ LONG':'▼ SHORT') + '</span></div>' +
    '<div style="margin:2px 0"><span class="amber">' + esc(p.country||'—') + '</span> <span class="muted">· ' + esc(p.region||'—') + '</span></div>' +
    '<div style="margin:4px 0"><span style="color:' + p.color + '">●</span> ' + esc(p.agent) + ' <span class="muted">(' + esc(p.team) + ')</span></div>' +
    '<div class="muted" style="font-size:11px">Conviction ' + fmtPct(p.conviction,0) + ' · Score ' + sgn(p.score,2) + '</div>' +
    '<div class="muted" style="font-size:11px;margin-top:4px">' + esc(p.thesis||'') + '</div>';
}

function globeLine(ctx, pts) {
  // trace un arc sur la face visible ; opacité selon la profondeur
  let started = false;
  ctx.beginPath();
  for (const [lat, lon] of pts) {
    const p = globeProject(lat, lon);
    if (p.z < 0.02) { started = false; continue; }
    if (!started) { ctx.moveTo(p.sx, p.sy); started = true; } else ctx.lineTo(p.sx, p.sy);
  }
  ctx.stroke();
}

function drawGlobe() {
  // arrêt propre quand l'onglet est quitté (le canvas n'est plus dans la page)
  if (!globeCanvas || !document.body.contains(globeCanvas)) { globeAnim = null; return; }
  const now = performance.now();
  if (!globeDrag && !globeHover && !globeSelected && now - globeLastInteract > 2500) globeRotY += 0.0018;
  const dpr = window.devicePixelRatio || 1;
  const { w, h, R } = globeSize();
  if (globeCanvas.width !== Math.round(w * dpr) || globeCanvas.height !== Math.round(h * dpr)) {
    globeCanvas.width = Math.round(w * dpr); globeCanvas.height = Math.round(h * dpr); globeGeo = null;
  }
  // pendant un glisser vertical : géométrie en basse résolution (fluide), pleine résolution au relâcher
  const geoDpr = globeDrag && dpr > 1 ? 1 : dpr;
  if (!globeGeo || globeGeo.rotX !== globeRotX || globeGeo.dpr !== geoDpr) globeBuildGeometry(geoDpr);
  const ctx = globeCtx;
  globeRenderSphere();
  const sc = globeRenderSphere.canvas;
  sc.getContext('2d').putImageData(globeImg, 0, 0);
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, globeCanvas.width, globeCanvas.height);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(sc, 0, 0, w, h);
  // fond étoilé discret derrière le disque + halo atmosphérique
  ctx.globalCompositeOperation = 'destination-over';
  const bg = ctx.createRadialGradient(w/2, h/2, R * 0.9, w/2, h/2, R * 1.25);
  bg.addColorStop(0, 'rgba(90,160,255,0.35)'); bg.addColorStop(0.35, 'rgba(60,120,220,0.10)'); bg.addColorStop(1, 'rgba(5,7,10,0)');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = '#05070a'; ctx.fillRect(0, 0, w, h);
  ctx.globalCompositeOperation = 'source-over';
  // graticule
  ctx.lineWidth = 0.6; ctx.strokeStyle = 'rgba(200,230,255,0.13)';
  for (let lat = -60; lat <= 60; lat += 30) { const pts = []; for (let lon = -180; lon <= 180; lon += 3) pts.push([lat, lon]); globeLine(ctx, pts); }
  for (let lon = -180; lon < 180; lon += 30) { const pts = []; for (let lat = -88; lat <= 88; lat += 3) pts.push([lat, lon]); globeLine(ctx, pts); }
  ctx.strokeStyle = 'rgba(255,153,0,0.35)'; ctx.lineWidth = 0.9;
  { const pts = []; for (let lon = -180; lon <= 180; lon += 2) pts.push([0, lon]); globeLine(ctx, pts); }
  // contour net du disque
  ctx.beginPath(); ctx.arc(w/2, h/2, R, 0, Math.PI*2); ctx.strokeStyle = 'rgba(140,200,255,0.35)'; ctx.lineWidth = 1; ctx.stroke();
  // épingles
  if (GLOBE) {
    const sorted = GLOBE.pins.map(p => ({p, pr: globeProject(p.lat, p.lon)}))
      .filter(o => o.pr.z >= 0.08).sort((a, b) => a.pr.z - b.pr.z);
    for (const o of sorted) {
      const p = o.p, pr = o.pr;
      const fade = Math.min(1, (pr.z - 0.08) / 0.25); // apparition douce près de l'horizon
      const pulse = 2 + Math.sin(now/400 + p.lat + p.lon) * 1.2;
      const isSel = globeSelected === p, isHov = globeHover === p;
      const size = (isSel || isHov ? 6.5 : 4.2) * (0.75 + 0.25 * pr.z);
      const ty = pr.sy - 7 * pr.z;
      ctx.globalAlpha = 0.6 * fade; ctx.strokeStyle = p.color; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(pr.sx, pr.sy); ctx.lineTo(pr.sx, ty); ctx.stroke();
      ctx.globalAlpha = 0.25 * fade;
      ctx.beginPath(); ctx.arc(pr.sx, ty, size + pulse, 0, Math.PI*2); ctx.fillStyle = p.color; ctx.fill();
      ctx.globalAlpha = fade;
      ctx.beginPath(); ctx.arc(pr.sx, ty, size, 0, Math.PI*2); ctx.fillStyle = p.color; ctx.fill();
      ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(0,0,0,0.6)'; ctx.stroke();
      if (p.direction === 'short') { ctx.strokeStyle = '#05070a'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(pr.sx - size*0.6, ty); ctx.lineTo(pr.sx + size*0.6, ty); ctx.stroke(); }
      if (isSel) { ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(pr.sx, ty, size + 3, 0, Math.PI*2); ctx.stroke(); }
      if (isHov || isSel) {
        ctx.font = 'bold 11px ' + getComputedStyle(document.body).fontFamily;
        const label = p.ticker, tw = ctx.measureText(label).width;
        ctx.fillStyle = 'rgba(5,7,10,0.85)'; ctx.fillRect(pr.sx + 9, ty - 8, tw + 8, 16);
        ctx.fillStyle = '#ffcc80'; ctx.fillText(label, pr.sx + 13, ty + 4);
      }
      ctx.globalAlpha = 1;
    }
  }
  globeAnim = requestAnimationFrame(drawGlobe);
}

async function ensureGlobeData() {
  if (!GLOBE) {
    try { const r = await fetch('/api/globe'); GLOBE = await r.json(); } catch(e) { GLOBE = {pins: [], legend: []}; }
  }
}

async function renderReports() {
  if (!REPORTS) {
    document.getElementById('content').innerHTML = '<div class="loader">Chargement des rapports des managers…</div>';
    try { const r = await fetch('/api/reports'); REPORTS = (await r.json()).reports; } catch(e) { REPORTS = []; }
  }
  await ensureGlobeData();
  let html = '';
  html += '<div class="panel-h">Globe des découvertes <span class="rt">' + (GLOBE ? GLOBE.pins.length : 0) + ' épingles · ' + (GLOBE ? GLOBE.legend.length : 0) + ' agents</span></div>';
  html += '<div class="panel-b" style="display:flex;gap:12px;padding:8px">';
  html += '<canvas id="globeCanvas" style="flex:1 1 560px;width:100%;max-width:780px;height:480px;background:#05070a;border:1px solid #1e3a5f;border-radius:6px;cursor:grab;display:block"></canvas>';
  html += '<div style="flex:1;min-width:220px"><div class="hdr-row" style="margin-bottom:6px">LÉGENDE (1 couleur = 1 agent)</div><div id="globeInfo" class="panel" style="margin-bottom:8px;padding:8px;font-size:12px"><span class="muted">Cliquez sur une épingle…</span></div><div style="max-height:320px;overflow-y:auto;font-size:11px">';
  if (GLOBE) for (const l of GLOBE.legend) html += '<div><span style="color:' + l.color + '">●</span> ' + esc(l.agent) + ' <span class="muted">— ' + esc(l.team) + ' (' + l.n_pins + ')</span></div>';
  html += '</div><div class="muted" style="font-size:10px;margin-top:8px">Glissez pour faire tourner la planète (rotation automatique au repos). Survolez ou cliquez une épingle pour le détail. ● = long, ● barré = short.</div></div>';
  html += '</div>';
  setTimeout(initGlobe, 50);

  for (const rep of REPORTS || []) {
    html += `<div class="team-block"><div class="panel-h">Rendu — Équipe ${esc(rep.team)} <span class="manager-tag">Manager: ${esc(rep.manager)}</span></div><div class="panel-b">`;
    html += `<div class="exec" style="margin-bottom:8px"><span class="hdr-row">Synthèse :</span> ${esc(rep.headline)}</div>`;
    html += '<table><tr><th>Agent</th><th>Périmètre</th><th>Découvertes / Signaux</th></tr>';
    for (const a of rep.agents) {
      const sigs = a.signals.map(s=>`<span class="${s.direction==='long'?'pos':'neg'}">${esc(s.ticker)} ${s.direction==='long'?'▲':'▼'} ${fmtPct(s.conviction,0)} (${sgn(s.score,2)})</span>`).join(' · ') || '<span class="muted">—</span>';
      html += `<tr><td class="amber">${esc(a.agent)}</td><td class="muted">${esc(a.scope)}</td><td>${sigs}</td></tr>`;
    }
    html += '</table></div></div>';
  }
  document.getElementById('content').innerHTML = html;
}

/* ============ MANAGERS ============ */
async function selectManager(mid) {
  if (selectedManager === mid) { selectedManager = null; document.querySelectorAll('#agentDetail, #managerDetail').forEach(n => n.remove()); renderReports(); return; }
  selectedManager = mid;
  let d;
  try { const r = await fetch('/api/manager/'+encodeURIComponent(mid)); d = await r.json(); } catch(e) { alert('Connexion perdue vers le serveur.'); return; }
  if (d.error) { alert('Manager introuvable : ' + d.error); return; }
  let html = `<div class="panel" style="margin-top:10px" id="managerDetail"><div class="panel-h">${esc(d.team)} — Compte rendu du manager <span class="rt">score ${sgn(d.aggregate_score,2)}</span></div><div class="panel-b">`;
  html += `<div class="exec" style="margin-bottom:8px"><span class="hdr-row">Synthèse :</span> ${esc(d.headline)}</div>`;
  html += '<table><tr><th>Agent</th><th>Périmètre</th><th class="num">Signaux</th><th class="num">Score moyen</th></tr>';
  for (const a of d.agents) {
    html += `<tr><td class="amber">${esc(a.agent)}</td><td class="muted">${esc(a.scope)}</td><td class="num">${a.n_signals}</td><td class="num ${a.mean_score>=0?'pos':'neg'}">${sgn(a.mean_score,2)}</td></tr>`;
  }
  html += '</table>';
  // Chat manager
  html += `<div class="grid" style="grid-template-columns:1fr 1fr;margin-top:10px">`;
  html += `<div><div class="chat-log" id="mgrChatLog">${(managerChatHistory[mid]||[]).map(m=>`<div class="q">❯ ${esc(m.q)}</div><div class="a">${esc(m.a)}</div>`).join('')||'<span class="muted">Demandez au manager les nouveautés de son équipe…</span>'}</div>`;
  html += `<div class="chat-input"><input type="text" id="mgrAskInput" placeholder="Question au manager : nouveautés, signaux, équipe…" onkeydown="if(event.key==='Enter')askManager('${esc(mid)}')"><button class="btn" onclick="askManager('${esc(mid)}')">ENVOYER</button></div></div>`;
  html += `<div><div class="muted" style="font-size:11px">Watchlist : ${d.watchlist && d.watchlist.length ? esc(d.watchlist.join(', ')) : 'vide'}</div></div>`;
    html += '</div>';
  // Esprit critique du manager : backtests indépendants + ajustements
  html += `<div style="margin-top:10px"><span class="hdr-row">Esprit critique du manager (backtests indépendants) :</span></div>`;
  html += `<div style="margin:6px 0"><button class="btn" onclick="runCritique('${esc(d.team)}')">LANCER LA REVUE DES STRATÉGIES</button> <span class="muted" id="critiqueStatus"></span></div>`;
  html += `<div id="critiqueBox" class="muted" style="font-size:11px">Chargement…</div>`;
  html += '</div></div></div>';
  document.querySelectorAll('#agentDetail, #managerDetail').forEach(n => n.remove());
  const el = document.getElementById('content');
  el.insertAdjacentHTML('beforeend', html);
  loadCritique('${esc(d.team)}');
  const det = document.getElementById('agentDetail');
  if (det) det.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

async function loadCritique(team) {
  const box = document.getElementById('critiqueBox');
  const status = document.getElementById('critiqueStatus');
  if (!box) return;
  try {
    const r = await fetch('/api/critique');
    const d = await r.json();
    let html = '';
    if (d.status === 'running') {
      status.textContent = 'Revue en cours… (' + (d.done_teams||[]).length + ' départements)';
      setTimeout(()=>loadCritique(team), 4000);
    }
    const c = (d.critiques||{})[team];
    if (!c) { box.innerHTML = '<span class="muted">Pas encore de revue. Clique sur \u00ab LANCER LA REVUE \u00bb pour que le manager backteste ses strat\u00e9gies.</span>'; return; }
    html += `<div class="exec" style="margin-bottom:6px">${esc(c.overall_verdict||'')}</div>`;
    if (c.backtests && c.backtests.length) {
      html += '<table><tr><th>Strat\u00e9gie</th><th class="num">Sharpe</th><th class="num">Rdt total</th><th class="num">Max DD</th><th>Verdict</th><th>Recommandation</th></tr>';
      for (const b of c.backtests) {
        html += `<tr><td class="amber">${esc(b.strategy)}</td><td class="num ${b.sharpe>=0?'pos':'neg'}">${sgn(b.sharpe,2)}</td><td class="num ${b.total_return>=0?'pos':'neg'}">${fmtPct(b.total_return,1)}</td><td class="num neg">${fmtPct(b.max_drawdown,1)}</td><td>${esc(b.verdict)}</td><td class="muted">${esc(b.recommendation)}</td></tr>`;
      }
      html += '</table>';
    }
    if (c.adjustments && c.adjustments.length) {
      html += '<div style="margin-top:6px"><span class="hdr-row">Ajustements propos\u00e9s :</span><ul style="margin:4px 0 0 16px">';
      for (const a of c.adjustments) html += `<li style="margin:2px 0">${esc(a)}</li>`;
      html += '</ul></div>';
    }
    box.innerHTML = html;
  } catch(e) { box.innerHTML = '<span class="neg">Connexion perdue \u2014 r\u00e9essaie dans un instant.</span>'; }
}

async function runCritique(team) {
  const status = document.getElementById('critiqueStatus');
  if (!status) return;
  try {
    const r = await fetch('/api/critique/run', {method:'POST'});
    const d = await r.json();
    if (d.status === 'started' || d.status === 'already_running') { status.textContent = 'Revue lanc\u00e9e \u2014 les managers backtestent leurs strat\u00e9gies (1-2 min)\u2026'; setTimeout(()=>loadCritique(team), 5000); }
  } catch(e) { status.textContent = 'Erreur de connexion.'; }
}


